```js
// Bad: only filters rgba(0,0,0,0)
colors.filter(c => c !== 'rgba(0,0,0,0)')

// Good: also filters rgb(0,0,0) when element is unset
colors.filter(c => {
  if (c !== 'rgba(0,0,0,0)') return true;
  // Climb DOM to check if ANY ancestor sets background
  let el = target;
  while (el && el !== document.body) {
    const bg = getComputedStyle(el).backgroundColor;
    if (bg !== 'rgba(0,0,0,0)' && bg !== 'rgb(0,0,0)') return true;
    el = el.parentElement;
  }
  return false;
})
